// Импортируем существующий генератор процедурного облачного фона.
import { mountBTSCloudBackground } from './btsCloudBackground.js';

// Находим только первый Hero-блок существующего сайта.
const hero = document.querySelector('.hero');

// Проверяем, что Hero-блок действительно существует на странице.
if (hero) {
  // Подключаем существующий генератор к Hero-блоку.
  const destroyCloudBackground = mountBTSCloudBackground(hero, {
    // Фиксируем облачность, выбранную пользователем в последней интерактивной настройке.
    density: 1.00,

    // Фиксируем более спокойную скорость движения облаков снизу вверх.
    speed: 0.099,

    // Фиксируем уменьшенный размер отдельных облачных масс.
    scale: 0.55,

    // Сохраняем выбранную мягкость границ без превращения облаков в однородный туман.
    softness: 0.07,

    // Фиксируем максимальный выбранный контраст светлого объёма и серо-голубых теней.
    contrast: 1.60,
  });

  // При окончательном закрытии страницы освобождаем графические ресурсы.
  window.addEventListener(
    'pagehide',
    destroyCloudBackground,
    { once: true }
  );
}
